function listEvenKeys(obj) {
  for (const key in obj) {
    if (obj[key] % 2 === 0) {
      console.log(key);
    }
  }
}

listEvenKeys({ a: 1, b: 2, c: 4, d: 7 });
// "b"
// "c"

