function describe(temp) {
  if (temp < 0) {
    return "freezing";
  } else if (temp < 20) {
    return "cold";
  } else {
    return "warm";
  }
}

console.log(describe(-5)); // "freezing"
console.log(describe(25)); // "warm"

function dayType(day) {
  switch (day) {
    case "Saturday":
    case "Sunday":
      return "weekend";
    default:
      return "weekday";
  }
}

console.log(dayType("Sunday")); // "weekend"
console.log(dayType("Monday")); // "weekday"

