assignment.solution:
function sizeLabel(size) {
  switch (size) {
    case "S":
      return "Small";
    case "M":
      return "Medium";
    case "L":
      return "Large";
    default:
      return "Unknown";
  }
}

console.log(sizeLabel("M")); // "Medium"

